import {parseCapture,uid,validateBackup,orderedTasks,markdown,localDate,validDate} from './core.js';
const $=id=>document.getElementById(id),KEY='unspool.workspace.v1';
const example='I need to finish the pitch deck today, urgent, 30 minutes. Book the train tickets tomorrow, 10 minutes. Explore a calmer landing page idea, 20 minutes. Send the prototype to the team, 15 minutes.';
const initial=()=>({version:1,tasks:parseCapture(example),draft:'',isSample:true});
let state=initial(),storageOK=true,filter='active',editing=null,undoState=null,toastTimeout,confirmAction=null;
try{const saved=localStorage.getItem(KEY);if(saved)state=validateBackup(JSON.parse(saved));}catch{storageOK=false;}
let focus={id:null,remaining:0,running:false,end:0};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('save-status').innerHTML=storageOK?'<i></i> Saved on this device':'Not saved · download a backup';}
function notify(message,undo=false){clearTimeout(toastTimeout);$('toast-message').textContent=message;$('undo').hidden=!undo;$('toast').hidden=false;toastTimeout=setTimeout(()=>{$('toast').hidden=true;},undo?15000:6000);}
function commit(fn,message){undoState=JSON.stringify(state);fn();save();render();notify(message,true);}
function dueLabel(due){if(!due)return '';const today=localDate();const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);if(due===today)return 'Today';if(due===localDate(tomorrow))return 'Tomorrow';return (due<today?'Overdue · ':'')+new Date(due+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short'});}
function render(){
 const active=state.tasks.filter(t=>!t.done),done=state.tasks.length-active.length,minutes=active.reduce((n,t)=>n+t.minutes,0),percent=state.tasks.length?Math.round(done/state.tasks.length*100):0;
 $('active-count').textContent=active.length;$('done-count').textContent=done;$('time-count').innerHTML=minutes>=60?`${Math.floor(minutes/60)}<span>h</span> ${minutes%60}<span>m</span>`:`${minutes}<span>m</span>`;$('tab-count').textContent=active.length;$('progress-number').textContent=percent+'%';$('progress-orbit').style.background=`conic-gradient(#9bb46c ${percent*3.6}deg,#edf0e5 0deg)`;
 $('sample-label').hidden=!state.isSample;const search=$('search').value.trim().toLowerCase();const tasks=orderedTasks(state.tasks).filter(t=>(filter==='all'||(filter==='done'?t.done:!t.done))&&(!search||(t.title+' '+t.category).toLowerCase().includes(search)));
 $('tasks').innerHTML=tasks.length?tasks.map(t=>`<article class="task ${t.done?'done':''}" data-id="${esc(t.id)}"><button class="check" data-action="toggle" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}">${t.done?'✓':''}</button><div class="task-body"><button class="task-name" data-action="edit" aria-label="Edit ${esc(t.title)}">${esc(t.title)}</button><div class="task-meta"><span class="tag ${t.category}">${t.category}</span><span>${t.minutes} min</span>${t.due?`<span>· ${esc(dueLabel(t.due))}</span>`:''}${t.priority==='high'?'<span class="priority">↑ High priority</span>':t.priority==='low'?'<span>↓ Low priority</span>':''}</div></div>${!t.done?`<button class="icon-button task-focus" data-action="focus" aria-label="Focus on ${esc(t.title)}">↗</button>`:''}</article>`).join(''):`<div class="empty"><div class="empty-icon">✳</div><h3>${search?'No matching thoughts.':filter==='done'?'Your little wins will live here.':state.tasks.length?'A little room to breathe.':'A fresh page. A lighter head.'}</h3><p>${search?'Try another word or clear your search.':filter==='done'?'Finish a task to celebrate your first one.':'Dictate a thought or add a task to begin.'}</p></div>`;
 document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter);});
 const next=orderedTasks(active)[0];$('next-title').textContent=next?next.title:'A clear head starts with one small step.';$('next-detail').textContent=next?`${next.minutes} minutes · ${next.category} · Give this one your attention.`:'Choose a task, take a breath, and give it your attention.';$('focus-next').disabled=!next;$('export').disabled=!state.tasks.length;
}
function syncDraft(){state.draft=$('capture').value;$('word-count').textContent=state.draft.trim()?state.draft.trim().split(/\s+/).length:0;$('organize').disabled=!state.draft.trim();}
function resetFocus(){focus={id:null,remaining:0,running:false,end:0};if($('focus-dialog').open)$('focus-dialog').close();}
function confirmation(title,message,action){$('confirm-title').textContent=title;$('confirm-message').textContent=message;confirmAction=action;$('confirm-dialog').showModal();$('confirm-cancel').focus();}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openEditor(id=null){editing=id;const t=state.tasks.find(t=>t.id===id);$('editor-title').textContent=t?'Edit your next step.':'One small next step.';$('task-title').value=t?.title||'';$('task-category').value=t?.category||'Work';$('task-priority').value=t?.priority||'normal';$('task-minutes').value=t?.minutes||25;$('task-due').value=t?.due||'';$('source-text').textContent=t?.source?'Original thought: “'+t.source+'”':'';$('delete-task').hidden=!t;$('editor').showModal();$('task-title').focus();}
function timerPaint(){const seconds=Math.ceil(focus.remaining/1000);$('timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('timer-toggle').textContent=focus.running?'Pause':focus.remaining<=0?'Session complete':'Start session';$('timer-toggle').disabled=focus.remaining<=0;}
function openFocus(id){const t=state.tasks.find(t=>t.id===id&&!t.done);if(!t)return;if(focus.id!==id){focus={id,remaining:t.minutes*60000,running:false,end:0};}$('focus-title').textContent=t.title;$('focus-message').textContent=focus.remaining<=0?'Time is up. Take a breath. Mark it done when you’re ready.':'Just this. Everything else can wait.';timerPaint();$('focus-dialog').showModal();}
setInterval(()=>{if(focus.running){focus.remaining=Math.max(0,focus.end-Date.now());if(focus.remaining===0){focus.running=false;$('focus-message').textContent='Time is up. Take a breath. Mark it done when you’re ready.';notify('Focus session complete. Take a breath.');}timerPaint();}},250);
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
$('capture').value=state.draft;syncDraft();$('capture').addEventListener('input',()=>{syncDraft();save();});
$('capture').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('organize').click();}});
$('sample').onclick=()=>{const apply=()=>{$('capture').value=example;syncDraft();save();$('capture').focus();};if(state.draft.trim())confirmation('Replace your draft?','This replaces the text in the capture box. Existing tasks stay in your plan.',apply);else apply();};
$('organize').onclick=()=>{let parsed;try{parsed=parseCapture($('capture').value);}catch(error){notify(error.message);return;}if(!parsed.length)return;const existing=state.isSample?[]:state.tasks;const seen=new Set(existing.map(t=>t.title.toLowerCase()));const fresh=parsed.filter(t=>{const key=t.title.toLowerCase();if(seen.has(key))return false;seen.add(key);return true;});if(existing.length+fresh.length>1000){notify('Your space is full. Export a backup and make room first.');return;}if(!fresh.length){notify('These thoughts are already in your plan. Your draft is kept.');return;}commit(()=>{if(state.isSample){state.tasks=[];resetFocus();}state.tasks.push(...fresh);state.draft='';state.isSample=false;filter='active';$('search').value='';$('capture').value='';syncDraft();},`${fresh.length} next step${fresh.length===1?'':'s'}. A little more clarity.`);};
$('new-task').onclick=()=>openEditor();
$('task-form').onsubmit=e=>{e.preventDefault();const title=$('task-title').value.trim(),minutes=Number($('task-minutes').value),due=$('task-due').value;if(!title){$('task-title').setCustomValidity('Give this step a name.');$('task-title').reportValidity();return;}if(!Number.isInteger(minutes)||minutes<1||minutes>240||(due&&!validDate(due))){notify('Check the duration and due date.');return;}if(!editing&&state.tasks.length>=1000){notify('Your workspace is full. Export a backup and make room first.');return;}const fields={title,minutes,due,category:$('task-category').value,priority:$('task-priority').value};commit(()=>{if(editing){const t=state.tasks.find(t=>t.id===editing);if(t)Object.assign(t,fields);if(focus.id===editing)resetFocus();}else state.tasks.push({id:uid(),...fields,source:'',createdAt:new Date().toISOString(),done:false});state.isSample=false;},editing?'Next step updated.':'One new possibility.');$('editor').close();};
$('task-title').oninput=()=>{$('task-title').setCustomValidity('');};
$('delete-task').onclick=()=>{commit(()=>{state.tasks=state.tasks.filter(t=>t.id!==editing);if(focus.id===editing)resetFocus();},'Task removed.');$('editor').close();};
$('tasks').onclick=e=>{const button=e.target.closest('[data-action]');if(!button)return;const id=button.closest('[data-id]').dataset.id;const t=state.tasks.find(t=>t.id===id);if(!t)return;if(button.dataset.action==='edit')openEditor(id);else if(button.dataset.action==='focus')openFocus(id);else commit(()=>{t.done=!t.done;if(focus.id===id)resetFocus();},t.done?'Task reopened.':'A little win. Nicely done.');};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$('search-toggle').onclick=()=>{$('search-row').hidden=!$('search-row').hidden;if(!$('search-row').hidden)$('search').focus();else{$('search').value='';render();}};$('search').oninput=render;
$('undo').onclick=()=>{if(!undoState)return;state=validateBackup(JSON.parse(undoState));undoState=null;resetFocus();$('capture').value=state.draft;syncDraft();save();render();notify('Change undone.');};
$('focus-next').onclick=()=>{const t=orderedTasks(state.tasks.filter(t=>!t.done))[0];if(t)openFocus(t.id);};
$('timer-toggle').onclick=()=>{if(focus.running){focus.remaining=Math.max(0,focus.end-Date.now());focus.running=false;}else{focus.end=Date.now()+focus.remaining;focus.running=true;}timerPaint();};
$('timer-reset').onclick=()=>{const t=state.tasks.find(t=>t.id===focus.id);if(t){focus.remaining=t.minutes*60000;focus.running=false;$('focus-message').textContent='Just this. Everything else can wait.';timerPaint();}};
$('focus-dialog').addEventListener('close',()=>{if(focus.running){focus.remaining=Math.max(0,focus.end-Date.now());focus.running=false;}});
$('finish-task').onclick=()=>{const t=state.tasks.find(t=>t.id===focus.id);if(t)commit(()=>{t.done=true;resetFocus();},'One less thing in your head. Well done.');};
['guide-open','voice-help'].forEach(id=>$(id).onclick=()=>$('guide').showModal());$('settings-open').onclick=()=>$('settings').showModal();$('workspace-nav').onclick=()=>{filter='active';$('search').value='';render();window.scrollTo({top:0,behavior:'smooth'});};
$('export').onclick=()=>{download('unspool-plan-'+localDate()+'.md',markdown(state.tasks),'text/markdown');notify('Your plan is ready to take with you.');};$('backup').onclick=()=>{download('unspool-backup-'+localDate()+'.json',JSON.stringify(state,null,2),'application/json');notify('Backup downloaded. Keep it somewhere safe.');};
$('restore').onclick=()=>$('restore-file').click();$('restore-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3_000_000)throw new Error('Choose a backup smaller than 3 MB.');const restored=validateBackup(JSON.parse(await file.text()));confirmation('Restore this workspace?',`Replace your current plan with ${restored.tasks.length} tasks from this backup? You can undo this change.`,()=>{commit(()=>{state=restored;resetFocus();$('capture').value=state.draft;syncDraft();filter='active';$('search').value='';},'Your workspace is restored.');$('settings').close();});}catch(error){notify(error instanceof SyntaxError?'This file is not valid JSON. Nothing was changed.':error.message);}finally{e.target.value='';}};
function clearWorkspace(){confirmation('Start with a clean slate?','This removes all tasks and your draft from this browser. Download a backup first if you want to keep them. You can undo this change.',()=>{commit(()=>{state={version:1,tasks:[],draft:'',isSample:false};resetFocus();$('capture').value='';syncDraft();filter='active';$('search').value='';},'A fresh page, just for you.');if($('settings').open)$('settings').close();$('capture').focus();});}
$('clear-demo').onclick=clearWorkspace;$('reset-workspace').onclick=clearWorkspace;$('confirm-cancel').onclick=()=>{$('confirm-dialog').close();confirmAction=null;};$('confirm-accept').onclick=()=>{const action=confirmAction;confirmAction=null;$('confirm-dialog').close();action?.();};$('confirm-dialog').addEventListener('cancel',()=>{confirmAction=null;});
$('capture').placeholder='Click here and dictate with Wispr Flow.\n\n“I need to finish the pitch today, 30 minutes. Book a train tomorrow. Maybe explore a new logo idea.”';
$('today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'}).toUpperCase()+' / A LITTLE ROOM TO THINK';render();if(!storageOK){$('save-status').textContent='Storage unavailable · export a backup';notify('Saved data could not be loaded. Export a backup before closing.');}
